#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=16
ROOT_ENV_FILE="$ENV_FILE"
LAUNCH_MODE="staging"
PAYSTACK_SECRET_KEY=""
MOOLRE_API_KEY=""
STRIPE_SECRET_KEY=""

set_supabase_provider_secrets() {
  local tmp count=0
  tmp=$(mktemp)
  chmod 600 "$tmp"

  if [[ -n "$PAYSTACK_SECRET_KEY" ]]; then
    printf 'PAYSTACK_SECRET_KEY=%s\n' "$PAYSTACK_SECRET_KEY" >> "$tmp"
    count=$((count + 1))
  fi
  if [[ -n "$MOOLRE_API_KEY" ]]; then
    printf 'MOOLRE_API_KEY=%s\n' "$MOOLRE_API_KEY" >> "$tmp"
    count=$((count + 1))
  fi
  if [[ -n "$STRIPE_SECRET_KEY" ]]; then
    printf 'STRIPE_SECRET_KEY=%s\n' "$STRIPE_SECRET_KEY" >> "$tmp"
    count=$((count + 1))
  fi

  if (( count == 0 )); then
    rm -f "$tmp"
    warn "no payment-provider secrets were entered"
    return 1
  fi

  if command -v npx >/dev/null 2>&1 && \
     npx --yes supabase@latest secrets set --project-ref "$SUPABASE_PROJECT_REF" --env-file "$tmp"; then
    rm -f "$tmp"
    printf '  %s✓ set%s %s Supabase Edge Function secret(s)\n' "$GREEN" "$RESET" "$count"
    return 0
  fi

  rm -f "$tmp"
  SKIPPED+=("Supabase payment secrets")
  warn "could not set Supabase secrets; add them in Edge Functions → Secrets"
  return 1
}

set_pages_service_role_secret() {
  if command -v npx >/dev/null 2>&1 && \
     printf '%s' "$SUPABASE_SERVICE_ROLE_KEY" | npx --yes wrangler@latest pages secret put \
       SUPABASE_SERVICE_ROLE_KEY --project-name "$CLOUDFLARE_PROJECT_NAME"; then
    printf '  %s✓ set%s Cloudflare Pages secret SUPABASE_SERVICE_ROLE_KEY\n' "$GREEN" "$RESET"
    return 0
  fi

  SKIPPED+=("Cloudflare Pages secret SUPABASE_SERVICE_ROLE_KEY")
  warn "could not set the Pages secret; add it in the Cloudflare dashboard"
  return 1
}

banner "Pulse manual go-live"

stage "Production safety gate"
say "Read docs/GO_LIVE_RUNBOOK.md before configuring live services."
warn "Public launch is blocked until role escalation, moderation, media isolation, Stripe, CSP, account deletion, and launch-placeholder issues are fixed."
step "Use staging for setup and sandbox testing while any gate remains open."
ask LAUNCH_MODE "Type staging or production:"
if [[ "$LAUNCH_MODE" != "production" ]]; then
  LAUNCH_MODE="staging"
  note "This run is staging-only. Keep signups restricted and use test credentials."
elif ! confirm "Have all production gates in the runbook been fixed and tested?"; then
  LAUNCH_MODE="staging"
  warn "continuing in staging mode"
fi
pause "Open the runbook and press Enter to continue."

stage "GitHub source of truth"
open_url "https://github.com/officiallykbk/Pulse"
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  printf '  %s✓ GitHub CLI is authenticated%s\n' "$GREEN" "$RESET"
else
  warn "GitHub CLI is not authenticated. Run: gh auth login -h github.com"
fi
step "Review git status, every diff, and the 11 local commits not yet on origin/main."
step "Commit only intended files; verify .env, SSH keys, and provider secrets are absent."
step "Push main, then confirm GitHub shows the same commit as local HEAD."
pause "Press Enter after the deployable commit is on GitHub."

stage "Domain, support, and ownership"
say "Choose values that match the legal entity used for provider onboarding."
ask APP_ORIGIN "Canonical HTTPS origin (for example https://example.com):"
ask SUPPORT_EMAIL "Support mailbox (for example support@example.com):"
ask ADMIN_EMAIL "Initial admin email:"
if [[ "$LAUNCH_MODE" == "production" && "$APP_ORIGIN" != https://* ]]; then
  warn "production APP_ORIGIN must start with https://"
fi
write_env VITE_PUBLIC_APP_URL "$APP_ORIGIN"
step "Record the legal business name, Pro prices, moderation owner, refund owner, and privacy/takedown contact in your operator records."
note "The support email is code-backed in src/config/appIdentity.ts; update it before the final push."

stage "Supabase project and keys"
open_url "https://supabase.com/dashboard/new"
step "Create a project, choose the closest suitable region, and save the database password in a password manager."
ask SUPABASE_PROJECT_REF "Project reference (the first part of <ref>.supabase.co):"
ask VITE_SUPABASE_URL "Project URL:"
if [[ "$VITE_SUPABASE_URL" == *"ncoiyubkjymurfazgcqk.supabase.co"* ]]; then
  warn "that is the old non-resolving project URL; create/restore a project and enter its new URL"
  ask VITE_SUPABASE_URL "New project URL:"
fi
ask_secret VITE_SUPABASE_ANON_KEY "Paste the anon/legacy anon key (input hidden):"
ENV_FILE="worker/.env"
ask_secret SUPABASE_SERVICE_ROLE_KEY "Paste the service-role key (input hidden):"
ENV_FILE="$ROOT_ENV_FILE"
write_env VITE_SUPABASE_URL "$VITE_SUPABASE_URL"
write_env VITE_SUPABASE_ANON_KEY "$VITE_SUPABASE_ANON_KEY"
ENV_FILE="worker/.env"
write_env SUPABASE_URL "$VITE_SUPABASE_URL"
write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
write_env STORAGE_BUCKET_NAME "videos"
ENV_FILE="$ROOT_ENV_FILE"

stage "Supabase migrations and storage"
if confirm "Run Supabase link and db push now?"; then
  npx --yes supabase@latest login
  npx --yes supabase@latest link --project-ref "$SUPABASE_PROJECT_REF"
  npx --yes supabase@latest db push
  npx --yes supabase@latest migration list
else
  SKIPPED+=("Supabase link, db push, and migration verification")
fi
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/storage/buckets"
step "Create public bucket videos with a 100 MB object limit for staging."
step "Create public bucket avatars with a 5 MB object limit."
warn "Do not permit private or 18+ uploads until storage isolation is fixed."
pause "Press Enter after both buckets exist."

stage "Supabase Auth and first admin"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/url-configuration"
step "Set Site URL to the final origin and add the pages.dev staging origin plus final domain as redirects."
step "Keep public signup disabled until the role and publishing gates are fixed."
step "Configure custom SMTP if email confirmation is enabled, then test confirmation and reset mail."
step "Create the admin user, then run the bootstrap-admin SQL from section C5 of the runbook using: $ADMIN_EMAIL"
pause "Press Enter after the admin role is verified."

stage "Paystack test account"
if confirm "Enable Paystack in this setup?"; then
  open_url "https://dashboard.paystack.com/#/settings/developer"
  step "Complete merchant verification and stay in test mode."
  ask VITE_PAYSTACK_PUBLIC_KEY "Paste the Paystack test public key:"
  ask_secret PAYSTACK_SECRET_KEY "Paste the Paystack test secret key:"
  write_env VITE_PAYSTACK_PUBLIC_KEY "$VITE_PAYSTACK_PUBLIC_KEY"
else
  SKIPPED+=("Paystack account and keys")
fi

stage "Moolre sandbox account"
if confirm "Enable direct Moolre Mobile Money in this setup?"; then
  open_url "https://moolre.com/"
  step "Complete merchant onboarding and request charge + transaction-verification API access."
  step "Confirm the MTN, VODAFONE, and AIRTELTIGO network codes with Moolre support."
  ask_secret MOOLRE_API_KEY "Paste the Moolre sandbox/API key:"
else
  SKIPPED+=("Moolre merchant onboarding and API key")
fi

stage "Stripe test account"
warn "Stripe remains blocked until price and Checkout return verification are fixed."
if confirm "Is the Stripe production gate fixed, and do you want to configure test mode?"; then
  open_url "https://dashboard.stripe.com/test/apikeys"
  step "Confirm your entity country is supported and complete account verification."
  ask_secret STRIPE_SECRET_KEY "Paste the Stripe test secret key:"
else
  SKIPPED+=("Stripe account and secret")
fi

stage "Payment secrets and Edge Function"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/functions"
if confirm "Set the entered provider secrets with the Supabase CLI?"; then
  set_supabase_provider_secrets || true
else
  SKIPPED+=("Supabase Edge Function payment secrets")
  step "Add PAYSTACK_SECRET_KEY, MOOLRE_API_KEY, and/or STRIPE_SECRET_KEY under Edge Functions → Secrets."
fi
if confirm "Deploy the verifypayment Edge Function now?"; then
  npx --yes supabase@latest functions deploy verifypayment --project-ref "$SUPABASE_PROJECT_REF"
  npx --yes supabase@latest functions list --project-ref "$SUPABASE_PROJECT_REF"
else
  SKIPPED+=("verifypayment Edge Function deployment")
fi

stage "Cloudflare Pages project"
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Create Pages → Import existing Git repository → officiallykbk/Pulse."
step "Use main, Vite, npm run build, dist, repository root, and NODE_VERSION=20."
ask CLOUDFLARE_PROJECT_NAME "Cloudflare Pages project name:"
step "Deploy once to obtain the pages.dev URL."
step "In Settings → Environment variables, add the VITE_ values saved in .env."
step "Also add runtime SUPABASE_URL and SUPABASE_ANON_KEY without the VITE_ prefix."
pause "Press Enter after the first Pages deployment succeeds."

stage "Cloudflare KV and service-role secret"
open_url "https://dash.cloudflare.com/?to=/:account/workers/kv/namespaces"
step "Create pulse-age-verifications-prod and pulse-rate-limits-prod."
step "Bind them to the Pages project as AGE_VERIFICATIONS and RATE_LIMITS exactly."
step "Use separate -preview namespaces if preview deployments are enabled."
if confirm "Set SUPABASE_SERVICE_ROLE_KEY as an encrypted Pages secret with Wrangler?"; then
  set_pages_service_role_secret || true
else
  SKIPPED+=("Cloudflare encrypted SUPABASE_SERVICE_ROLE_KEY")
fi
step "Redeploy after variables, secrets, and bindings change."
pause "Press Enter after /api/auth/session and /api/age/status return JSON."

stage "Custom domain and email"
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Attach the custom domain to the Pages project and wait for active SSL."
step "Update VITE_PUBLIC_APP_URL and redeploy if the first deployment used pages.dev."
step "Update Supabase Auth Site URL and redirects."
step "Create $SUPPORT_EMAIL plus the SMTP sender; configure SPF, DKIM, and DMARC."
step "Replace the bolt.new social image and all launch-domain/support placeholders in source."
pause "Press Enter after HTTPS and email delivery are verified."

stage "Transcoder VM"
warn "Do not start a production worker until moderation and storage isolation are fixed."
open_url "https://cloud.oracle.com/compute/instances"
ask WORKER_ID "Worker ID (for example oracle-arm-01):"
ask CDN_BASE_URL "Optional CDN base URL (blank uses direct Supabase Storage):"
ENV_FILE="worker/.env"
write_env WORKER_ID "$WORKER_ID"
write_env POLL_INTERVAL_MS "5000"
write_env CONCURRENCY "1"
write_env FFMPEG_PATH "/usr/bin/ffmpeg"
write_env FFPROBE_PATH "/usr/bin/ffprobe"
write_env TEMP_DIR "/tmp/pulse_worker"
if [[ -n "$CDN_BASE_URL" ]]; then write_env CDN_BASE_URL "$CDN_BASE_URL"; fi
ENV_FILE="$ROOT_ENV_FILE"
step "Provision Ubuntu, restrict SSH to trusted IPs, clone the exact production commit, and run worker/setup-oracle-vm.sh."
step "Create /opt/pulse-worker/.env manually because the setup script's * glob does not copy dotfiles."
step "Copy the values from worker/.env, lock permissions, and enable/start pulse-transcoder."
pause "Press Enter after systemctl status and journalctl show a healthy worker."

stage "Ads and optional CDN"
warn "Do not configure live VAST until the CSP gate is fixed."
if confirm "Configure an ExoClick test/in-stream zone now?"; then
  open_url "https://admin.exoclick.com/"
  step "Create in-stream VAST only; disable pop-under, redirect, banner, and interstitial formats."
  ask VITE_EXOCLICK_ZONE_ID "ExoClick zone ID (blank if using a direct URL):"
  ask VITE_EXOCLICK_VAST_URL "Optional direct ExoClick VAST URL:"
  [[ -n "$VITE_EXOCLICK_ZONE_ID" ]] && write_env VITE_EXOCLICK_ZONE_ID "$VITE_EXOCLICK_ZONE_ID"
  [[ -n "$VITE_EXOCLICK_VAST_URL" ]] && write_env VITE_EXOCLICK_VAST_URL "$VITE_EXOCLICK_VAST_URL"
else
  SKIPPED+=("VAST ad account and CSP verification")
fi
if [[ -n "$CDN_BASE_URL" ]]; then
  open_url "https://dash.bunny.net/cdn/add"
  step "Use the Supabase public videos object URL as origin; long-cache .ts and short-cache .m3u8."
  step "Keep private and age-restricted objects off every public pull zone."
else
  note "CDN skipped; staging can use direct Supabase Storage URLs."
fi

stage "Acceptance and launch decision"
if confirm "Run local lint, typecheck, tests, and production builds now?"; then
  npm run lint
  npm run typecheck
  npm test
  npm run build
  npm --prefix worker run build
  npm --prefix worker test
else
  SKIPPED+=("local verification suite")
fi
step "Complete every applicable checkbox in sections 12 and 14 of docs/GO_LIVE_RUNBOOK.md."
step "Test auth, KV persistence, upload/transcode/moderation, access control, payments, ads, sharing, and PWA install on real devices."
if [[ "$LAUNCH_MODE" == "production" ]]; then
  if confirm "Do all production gates and acceptance checks pass with named operators?"; then
    note "Production setup is ready for the final live-credential switch and monitored release."
  else
    SKIPPED+=("production approval; remain in staging")
    warn "remain in staging and keep live credentials disabled"
  fi
else
  note "Staging setup complete. Do not install live credentials yet."
fi

ENV_FILE="${ROOT_ENV_FILE} and worker/.env"
finish
